// ====================================================
// UNIVERSAL AVATAR RENDERER
// ====================================================
window.ETHITH_RENDER_USER_AVATAR = function(user, size, extraClass, extraStyle) {
  var s = size || 36;
  var cls = extraClass || "";
  var st = extraStyle || "";
  var u = user || {};

  var avatarObj = null;
  if (u.avatar) {
    if (typeof u.avatar === "string") {
      avatarObj = (window.ETHITH_AVATARS || []).find(function(a) { return a.id === u.avatar; });
    } else if (u.avatar.id) {
      avatarObj = (window.ETHITH_AVATARS || []).find(function(a) { return a.id === u.avatar.id; }) || u.avatar;
    }
  }

  if (avatarObj && avatarObj.svg) {
    return '<div class="eth-avatar-circle ' + cls + '" style="width:' + s + 'px;height:' + s + 'px;border-radius:50%;overflow:hidden;flex-shrink:0;box-shadow:0 2px 8px rgba(0,0,0,0.18);display:inline-flex;align-items:center;justify-content:center;background:' + (avatarObj.bg || '#1e293b') + ';border:2px solid ' + (avatarObj.border || 'rgba(255,255,255,0.25)') + ';' + st + '" title="' + (avatarObj.name || '') + '">' +
      avatarObj.svg +
    '</div>';
  }

  // Fallback: Initial letter
  var initial = (u.name && u.name.trim()) ? u.name.trim().charAt(0).toUpperCase() : "U";
  return '<div class="eth-avatar-circle eth-avatar-fallback ' + cls + '" style="width:' + s + 'px;height:' + s + 'px;border-radius:50%;background:linear-gradient(135deg, #2563eb, #1d4ed8);color:#ffffff;font-weight:800;font-size:' + Math.round(s * 0.45) + 'px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;border:2px solid rgba(255,255,255,0.2);box-shadow:0 2px 6px rgba(0,0,0,0.15);' + st + '">' +
    initial +
  '</div>';
};

// ====================================================
// PACK OPENING DROP LOGIC (RNG & 15-PACK PITY SYSTEM)
// ====================================================
window.ETHITH_OPEN_PACK = function(packId, user) {
  var pack = (window.ETHITH_PACKS || []).find(function(p) { return p.id === packId; });
  if (!pack) return null;

  if (!user) user = (window.EthithApp && window.EthithApp.state && window.EthithApp.state.user) || {};
  var userKey = (user.email || user.name || 'guest').toLowerCase().trim().replace(/\s+/g, '_');
  var pityStorageKey = 'ethith_pack_pity_' + userKey;
  var currentPity = 0;
  try {
    currentPity = Number(user.pityCount || localStorage.getItem(pityStorageKey) || 0);
  } catch(e) {}

  // 15-PACK PITY RULE: 100% Epic or Legendary (50/50)
  var isPityTriggered = (currentPity >= 15);
  var rarity = "Common";

  if (isPityTriggered) {
    rarity = (Math.random() < 0.5) ? "Legendary" : "Epic";
    currentPity = 0;
  } else {
    var rand = Math.random() * 100;
    if (rand < 7) rarity = "Legendary";
    else if (rand < 25) rarity = "Epic";
    else if (rand < 55) rarity = "Rare";
    else rarity = "Common";

    if (rarity === "Epic" || rarity === "Legendary") {
      currentPity = 0;
    } else {
      currentPity += 1;
    }
  }

  user.pityCount = currentPity;
  try { localStorage.setItem(pityStorageKey, String(currentPity)); } catch(e) {}

  if (pack.type === "daily") {
    var roll = Math.random() * 100;
    if (roll < 60) {
      var coinAmounts = [];
      if (rarity === "Legendary") coinAmounts = [1200, 1600, 2200];
      else if (rarity === "Epic") coinAmounts = [500, 650, 850];
      else if (rarity === "Rare") coinAmounts = [240, 320, 420];
      else coinAmounts = [100, 160, 200];
      var amount = coinAmounts[Math.floor(Math.random() * coinAmounts.length)];
      return {
        type: "coins",
        rarity: rarity,
        amount: amount,
        name: amount + " ETHITH Coin!",
        desc: "Kunlik qutidan tushgan xazina! Hamyoningizga darhol qo'shildi!",
        icon: "🪙"
      };
    } else if (roll < 85) {
      var pz = window.ETHITH_GET_RANDOM_PRIZE ? window.ETHITH_GET_RANDOM_PRIZE(rarity) : null;
      return {
        type: "prize",
        rarity: (pz ? pz.rarity : rarity),
        item: pz,
        name: pz ? pz.name : "Kutilmagan Sovg'a",
        desc: pz ? pz.desc : "Yangi sovrin!",
        icon: pz ? pz.icon : "🎁"
      };
    } else {
      var unlEmojis = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) {
        return !e.isDefault && (e.rarity === rarity || !rarity);
      });
      if (!unlEmojis.length) unlEmojis = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) { return !e.isDefault; });
      var em = unlEmojis[Math.floor(Math.random() * unlEmojis.length)];
      return {
        type: "emoji",
        rarity: em.rarity,
        emoji: em.emoji,
        name: em.emoji + " " + em.name,
        desc: "Telegram chat va reaksiyalar uchun ochildi!",
        icon: em.emoji
      };
    }
  }

  if (pack.type === "prize") {
    var pz = window.ETHITH_GET_RANDOM_PRIZE ? window.ETHITH_GET_RANDOM_PRIZE(rarity) : null;
    return {
      type: "prize",
      rarity: (pz ? pz.rarity : rarity),
      item: pz,
      name: pz ? pz.name : "Omadli Sovg'a",
      desc: pz ? pz.desc : "Ajoyib o'zbekcha sovrin!",
      icon: pz ? pz.icon : "💎",
      coinPrice: pz ? pz.price : (rarity === "Legendary" ? 1000 : (rarity === "Epic" ? 450 : (rarity === "Rare" ? 200 : 80)))
    };
  }

  if (pack.type === "emoji") {
    var matching = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) {
      return !e.isDefault && (e.rarity === rarity || !rarity);
    });
    if (!matching.length) matching = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) { return !e.isDefault; });
    var chosen = matching[Math.floor(Math.random() * matching.length)];
    return {
      type: "emoji",
      rarity: chosen.rarity,
      emoji: chosen.emoji,
      name: chosen.emoji + " " + chosen.name,
      desc: "Telegram chat va barcha reaksiyalarda endi erkin foydalanishingiz mumkin!",
      icon: chosen.emoji
    };
  }

  if (pack.type === "avatar_boy") {
    var boys = (window.ETHITH_AVATARS || []).filter(function(a) {
      return a.gender === "boy" && (a.rarity === rarity || !rarity);
    });
    if (!boys.length) boys = (window.ETHITH_AVATARS || []).filter(function(a) { return a.gender === "boy"; });
    var chosen = boys[Math.floor(Math.random() * boys.length)];
    return {
      type: "avatar",
      rarity: chosen.rarity,
      avatar: chosen,
      name: chosen.name,
      desc: chosen.tagline,
      icon: chosen.name
    };
  }

  if (pack.type === "avatar_girl") {
    var girls = (window.ETHITH_AVATARS || []).filter(function(a) {
      return a.gender === "girl" && (a.rarity === rarity || !rarity);
    });
    if (!girls.length) girls = (window.ETHITH_AVATARS || []).filter(function(a) { return a.gender === "girl"; });
    var chosen = girls[Math.floor(Math.random() * girls.length)];
    return {
      type: "avatar",
      rarity: chosen.rarity,
      avatar: chosen,
      name: chosen.name,
      desc: chosen.tagline,
      icon: chosen.name
    };
  }

  if (pack.type === "mega") {
    var catRoll = Math.random() * 100;
    if (catRoll < 25) {
      var coinAmounts = [];
      if (rarity === "Legendary") coinAmounts = [1250, 1650, 2500];
      else if (rarity === "Epic") coinAmounts = [600, 750, 950];
      else if (rarity === "Rare") coinAmounts = [300, 420, 500];
      else coinAmounts = [180, 220, 260];
      var amount = coinAmounts[Math.floor(Math.random() * coinAmounts.length)];
      return {
        type: "coins",
        rarity: rarity,
        amount: amount,
        name: amount + " ETHITH Coin!",
        desc: "Universal Mega Packdan xazina! Hamyoningizga darhol qo'shildi!",
        icon: "🪙"
      };
    } else if (catRoll < 50) {
      var pz = window.ETHITH_GET_RANDOM_PRIZE ? window.ETHITH_GET_RANDOM_PRIZE(rarity) : null;
      return {
        type: "prize",
        rarity: (pz ? pz.rarity : rarity),
        item: pz,
        name: pz ? pz.name : "Omadli Sovg'a",
        desc: pz ? pz.desc : "Mega Packdan tushgan maxsus sovrin!",
        icon: pz ? pz.icon : "💎",
        coinPrice: pz ? pz.price : (rarity === "Legendary" ? 1000 : (rarity === "Epic" ? 450 : 200))
      };
    } else if (catRoll < 70) {
      var matching = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) {
        return !e.isDefault && (e.rarity === rarity || !rarity);
      });
      if (!matching.length) matching = (window.ETHITH_CHAT_EMOJIS || []).filter(function(e) { return !e.isDefault; });
      var chosenEm = matching[Math.floor(Math.random() * matching.length)];
      return {
        type: "emoji",
        rarity: chosenEm.rarity,
        emoji: chosenEm.emoji,
        name: chosenEm.emoji + " " + chosenEm.name,
        desc: "Universal Mega Packdan chat emojisi ochildi!",
        icon: chosenEm.emoji
      };
    } else if (catRoll < 85) {
      var boys = (window.ETHITH_AVATARS || []).filter(function(a) {
        return a.gender === "boy" && (a.rarity === rarity || !rarity);
      });
      if (!boys.length) boys = (window.ETHITH_AVATARS || []).filter(function(a) { return a.gender === "boy"; });
      var chosenBoy = boys[Math.floor(Math.random() * boys.length)];
      return {
        type: "avatar",
        rarity: chosenBoy.rarity,
        avatar: chosenBoy,
        name: chosenBoy.name,
        desc: chosenBoy.tagline,
        icon: chosenBoy.name
      };
    } else {
      var girls = (window.ETHITH_AVATARS || []).filter(function(a) {
        return a.gender === "girl" && (a.rarity === rarity || !rarity);
      });
      if (!girls.length) girls = (window.ETHITH_AVATARS || []).filter(function(a) { return a.gender === "girl"; });
      var chosenGirl = girls[Math.floor(Math.random() * girls.length)];
      return {
        type: "avatar",
        rarity: chosenGirl.rarity,
        avatar: chosenGirl,
        name: chosenGirl.name,
        desc: chosenGirl.tagline,
        icon: chosenGirl.name
      };
    }
  }

  return null;
};
